/* BmsOutNoticeMapper.selectInventoryList : 미승인재고 리스트 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM ( SELECT A.IN_NO , CASE WHEN (SELECT TOP 1 tcfs.REFERENCE_NO_ID FROM TB_COM_FILE_SHARE tcfs WHERE A.OD_JOB_NO = tcfs.FUNC_JOB_NO) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
, '예정' AS lastPodStatus , '조회' AS blStatus
, A.CARRYIN_DATE , A.OUT_NOTICE_DATE , A.PERIOD_OVER_DATE , A.BL_NO , A.MBL_NO , A.CARGO_REFERENCE_NO , A.COMMODITY_ITEM_LOC , A.AR_DATE , A.VESSEL_FLIGHT , A.VOYAGE , A.PKG_TYPE , ISNULL(A.STOCK_CT, 0) - ISNULL(B.APPROVAL_CT, 0) AS INOUT_NOTICE_PLAN_CT , ISNULL(A.STOCK_WT, 0) - ISNULL(B.APPROVAL_WT, 0) AS INOUT_NOTICE_PLAN_WT , A.LOCATION_PLACE , A.OD_JOB_NO , A.CUSTOMER_CODE , A.CUSTOMER_NAME , A.SHIPPER_CODE , A.SHIPPER_NAME , A.CONSIGNEE_CODE , A.CONSIGNEE_NAME , A.CONSIGNEE_ADDRESS_1 , dbo.Cryptography(A.OD_JOB_NO, A.CONSIGNEE_BUSINESS_ID, 1) AS CONSIGNEE_BUSINESS_ID , dbo.Cryptography(A.OD_JOB_NO, A.CONSIGNEE_TEL, 1) AS CONSIGNEE_TEL , A.NOTIFY_CODE , A.NOTIFY_NAME , A.NOTIFY_ADDRESS_1 , dbo.Cryptography(A.OD_JOB_NO, A.NOTIFY_TEL, 1) AS NOTIFY_TEL , A.CUSTOMS_REPORT_NO , A.CNTR_NO , A.REFERENCE_NO , A.REGISTER_USER_ID , (SELECT TOP 1 tsu.USER_NAME FROM TB_SMS_USER tsu WHERE A.REGISTER_USER_ID = tsu.USER_ID) AS REGISTER_USER_NAME , A.REGISTER_DATE_TIME , A.UPDATE_USER_ID , (SELECT TOP 1 tsu.USER_NAME FROM TB_SMS_USER tsu WHERE A.UPDATE_USER_ID = tsu.USER_ID) AS UPDATE_USER_NAME , A.UPDATE_DATE_TIME , A.CD_TYPE , IIF(A.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(A.CD_TYPE = 'N', 1, 0) AS GENERAL_CNT , A.IN_CLASS , 'STOCK' AS SRCH_GBN FROM TB_BMS_IN A WITH (NOLOCK) LEFT JOIN TB_BMS_OUT_PLAN B WITH (NOLOCK) ON A.IN_NO = B.IN_NO AND B.APPROVAL_CLASS = '31' AND B.OUT_YN = 'N' WHERE 1=1 AND ISNULL(A.STOCK_WT, 0) - ISNULL(B.APPROVAL_WT, 0) > 0 AND NOT EXISTS ( SELECT 1 FROM TB_BMS_OUT_NOTICE WITH(NOLOCK) WHERE CARGO_REFERENCE_NO = A.CARGO_REFERENCE_NO AND LAST_POD_STATUS = 'BMS04' )
AND 1 = 0
) AA

/* BmsOutNoticeMapper.selectBmsOutNoticeListBySrchNo : 조회번호, 타입에 따라 반출통고 데이터 조회 */
SELECT A.IN_NO , A.OUT_NOTICE_NO , A.OUT_NOTICE_DATE , A.BL_NO , A.CARGO_REFERENCE_NO , (SELECT B.IN_CLASS FROM TB_BMS_IN B WITH (NOLOCK) WHERE A.IN_NO = B.IN_NO) AS IN_CLASS , A.MBL_NO , 'NOTICE' AS SRCH_GBN FROM TB_BMS_OUT_NOTICE A LEFT JOIN TB_BMS_IN tbi WITH (NOLOCK) ON tbi.IN_NO = A.IN_NO
WHERE tbi.${srchNoType} = #{srchNo}
WHERE A.${srchNoType} = #{srchNo}

