/* BmsOutNoticeMapper.updateBmsOutNotice : 등록 ENTRY - 반출통고 UPDATE */
UPDATE TB_BMS_OUT_NOTICE

	   CUSTOMS_CODE = (SELECT BMS_CUSTOMS_CODE FROM TB_SMS_ENT_BUSINESS WHERE ENT_BUSINESS_CODE = #{entBusinessCode})
	 , CUSTOMS_DPT_CODE = (SELECT BMS_CUSTOMS_DPT_CODE FROM TB_SMS_ENT_BUSINESS WHERE ENT_BUSINESS_CODE = #{entBusinessCode})
 	 , IN_NO = #{inNo}
	 , CARGO_REFERENCE_NO = #{cargoReferenceNo}
	 , BL_NO = #{blNo}
	 , MBL_NO = #{mblNo}

	 , LAST_POD_STATUS = 'BMS01'
	 , LAST_POD_DATE = ''
	 , LAST_POD_RAQ_DATE = ''

	 , OUT_NOTICE_DATE = #{outNoticeDate}
	 , PERIOD_OVER_DATE = #{periodOverDate}
	 , PKG_TYPE = #{pkgType}
	 , NOTICE_CT = #{noticeCt}
	 , NOTICE_WT = #{noticeWt}
	 , CUSTOMER_CODE = #{customerCode}
	 , CUSTOMER_NAME = #{customerName}
	 , CUSTOMER_ZIPCODE = #{customerZipcode}
	 , CUSTOMER_ADDRESS_1 = #{customerAddress1}
	 , CUSTOMER_ADDRESS_2 = #{customerAddress2}
	 , CUSTOMER_TEL = dbo.Cryptography(#{cargoReferenceNo}, #{customerTel}, 0)
	 , CUSTOMER_REMARKS = #{customerRemarks}
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()

 WHERE OUT_NOTICE_NO = #{outNoticeNo}

