/* BmsOutNoticeMapper.updateBmsInDate : 등록 ENTRY - 반입 통고일자, 체화일자 UPDATE */
UPDATE TB_BMS_IN

	   OUT_NOTICE_DATE = #{outNoticeDate}
	 , PERIOD_OVER_DATE = #{periodOverDate}
	 , UPDATE_USER_ID = #{updateUserId}
	 , UPDATE_DATE_TIME = GETDATE()

 WHERE IN_NO = #{inNo}

/* BmsOutNoticeMapper.updateOutNoticeYn : 반출통고누락 반출통고등록여부 UPDATE */
UPDATE TB_BMS_OUT_NOTICE_PLAN

	   OUT_NOTICE_YN = 'Y'
	 , REGISTER_USER_ID = #{registerUserId}
	 , REGISTER_DATE_TIME = GETDATE()

 WHERE IN_NO = #{inNo}

